73	    void missingInspectionPausesWholeBatch() throws Exception {
74	        declareOk("d-1", "B-MISS", List.of("H1", "H2", "H3"));
75	        preQuarantineOk("B-MISS", "pq-1");
76	        inspectOk("B-MISS", "i-1", "H1");
