        throw new UnsupportedOperationException("骨架");
    }

    public Optional<RiskBindingRow> findBinding(long batchId) {
        throw new UnsupportedOperationException("骨架");
    }

    /** 行锁读取风险绑定（须在事务内调用），用于变更/结果与批次状态互斥。 */
    public Optional<RiskBindingRow> findBindingForUpdate(long batchId) {
        throw new UnsupportedOperationException("骨架");
    }

