    // ---------- 风险变更 ----------

    @Test
    @DisplayName("未完成清单提高等级原子扩充：保留既有结果，版本加1，降低与同级拒绝")
    void expandOpenChecklistAtomically() throws Exception {
        ready("B-EXP", 20);
        bindRisk("rb-1", "B-EXP", "NORMAL", "RULE-1", heads(20), 0);
        // NORMAL 20 只 → 2 只；先出 1 只结果，清单仍 OPEN
