        assertEquals("RULE-2", expanded.ruleVersion());
        assertEquals("OPEN", expanded.status());

        RiskSummaryView.ChecklistView checklist = getRisk("B-EXP").checklists().get(0);
        assertEquals(6, checklist.samples().size());
