    @Test
    @DisplayName("风险对象不存在404；未绑定批次查询 controlled=false")
    void notFoundAndUnboundView() throws Exception {
        declareOk("d-1", "B-NOBIND", heads(2));
        RiskSummaryView summary = getRisk("B-NOBIND");
        assertFalse(summary.controlled());
